import time
import math

def throttle(minutes: float):
    """
    Decorator to throttle function calls to at most once every `minutes` seconds.

    Args:
        minutes: The threshold time in minutes (e.g., 1 for once per minute)

    Returns:
        A decorator function that wraps the target function to enforce throttling.
    """
    class Throttle:
        def __init__(self, minutes):
            self.minutes = minutes
            self.last_time = -math.inf  # Initialize with a very small number
                                    # to ensure the first call is allowed

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                current_time = time.time()
                # If the current time is within the allowed window, skip the call
                if current_time - self.last_time < self.minutes * 60:
                    return
                # Update the last call time and call the function
                self.last_time = current_time
                return func(*args, **kwargs)
            return wrapper

    return Throttle(minutes)

