import time

class Throttle:
    def __init__(self, period=60):
        self.period = period  # in seconds
        self.last = 0  # last call time

    def __call__(self, func):
        def wrapper(*args, **kwargs):
            now = time.time()
            if now - self.last < self.period:
                # Sleep for the remaining time to reach the next minute
                time.sleep(self.period - (now - self.last))
            self.last = now  # update the last call time
            return func(*args, **kwargs)
        return wrapper

@Throttle(60)
def my_function():
    print("Function executed at:", time.ctime())

