import time
import threading

def throttle(minutes):
    class Throttle:
        def __init__(self, minutes):
            self.minutes = minutes
            self.lock = threading.Lock()
            self.last_call = {}

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                key = func.__qualname__
                with self.lock:
                    current_time = time.time()
                    if current_time - self.last_call.get(key, 0) < self.minutes * 60:
                        raise Exception("Throttled: can only call once per minute")
                    self.last_call[key] = current_time  # Update the last call time
                return func(*args, **kwargs)
            return wrapper

    return Throttle(minutes)

