import time

def throttle(seconds):
    def decorator(func):
        last_call = 0  # Track the last time the function was called

        def wrapper(*args, **kwargs):
            nonlocal last_call
            current_time = time.time()
            if current_time - last_call < seconds:
                return "Too fast, please wait"
            last_call = current_time  # Update the last call time
            return func(*args, **kwargs)
        return wrapper
    return decorator

