import statistics

def column_stats(table):
    headers = table[0]
    # Map header names to their corresponding data
    column_data = {
        header: [row[i] for row in table[1:]]
        for i, header in enumerate(headers)
    }

    result = {}

    for header, data in column_data.items():
        # Mean: population average
        mean = statistics.mean(data)
        # Median: middle value
        median = statistics.median(data)
        # Mode: most frequent value
        # If multimode, take the first
        mode = statistics.multimode(data)[0]
        # Variance: population variance
        variance = statistics.pvariance(data)

        result[header] = {
            'mean': mean,
            'median': median,
            'mode': mode,
            'variance': variance
        }

    return result

