import sys

def main():
    # Read the input from standard input, split into a list of strings
    labels = sys.stdin.read().split()

    # Determine the unique categories in the order they first appear
    unique = []
    for label in labels:
        if label not in unique:
            unique.append(label)

    # Create a dictionary to map each unique label to its index
    label_to_index = {label: i for i, label in enumerate(unique)}

    # Generate and print the one-hot encoded matrix
    for label in labels:
        row = [0] * len(unique)
        row[label_to_index[label]] = 1
        print(' '.join(map(str, row)))

