import sys

def main():
    # Step 1: Read all input from standard input
    input_str = sys.stdin.read().strip()
    labels = input_str.split()  # Split by whitespace to handle multi-line input

    # Step 2: Extract unique labels and map them to indices
    unique_labels = []
    label_to_index = {}

    for label in labels:
        if label not in label_to_index:
            label_to_index[label] = len(unique_labels)
            unique_labels.append(label)

    # Step 3: Generate one-hot encoded rows
    for label in labels:
        index = label_to_index[label]
        row = [0] * len(unique_labels)
        row[index] = 1
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    main()

import subprocess
import time
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

def watch_file(args):
    class MyHandler(FileSystemEventHandler):
        def on_modified(self, event):
            if event.src_path == args.file:
                # Execute the callback command
                subprocess.run(args.callback, shell=True)

    observer = Observer()
    observer.schedule(MyHandler(), path=args.file, recursive=False)
    observer.start()

    try:
        # Keep the process running until the user stops it (Ctrl+C)
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

