def watch_file(
    path: str | Path,
    callback: Callable[[str | Path], None],
) -> None:
    """Watch a file and call the callback when it changes.

    Args:
        path: The path to the file to monitor.
        callback: A function to invoke when the file is modified. It receives the
                  modified file path as an argument.

    Returns:
        None
    """
    class FileChangeHandler(FileSystemEventHandler):
        def __init__(self, callback, path):
            self.callback = callback
            self.path = path

        def on_modified(self, event):
            if event.src_path == str(self.path):
                self.callback(event.src_path)

    observer = Observer()
    observer.schedule(FileChangeHandler(callback, path), path)
    observer.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

