def watch_file(
    path: str | Path,
    callback: callable,
) -> None:
    """Watch a file for changes and call the callback when it changes."""
    last_mod_time = None
    while True:
        try:
            current_mod_time = os.path.getmtime(str(path))
        except Exception as e:
            # Handle errors like file not found, permissions, etc.
            time.sleep(1)
            continue

        if last_mod_time is None or current_mod_time != last_mod_time:
            callback(path)
            last_mod_time = current_mod_time

        time.sleep(1)

