function throttle(func) {
  let lastCallTime = -Infinity; // Initialize to a very early time
  return function(...args) {
    const now = Date.now();
    if (now - lastCallTime >= 60 * 1000) {
      func.apply(this, args);
      lastCallTime = now;
    }
  };
}

