function throttle(func) {
  // Initialize the last execution time to -Infinity to allow the
  // first call to be executed immediately.
  let lastExecutionTime = -Infinity;

  // Return the wrapped function that will control when `func` is called.
  return function (...args) {
    const now = Date.now();

    // If the current time is at least 60 seconds after the last execution,
    // it's safe to call the original function again.
    if (now - lastExecutionTime >= 60000) {
      lastExecutionTime = now; // Update the last execution time
      func(...args); // Execute the original function
    }
  };
}

