/**
 * Throttle a function to run at most once per minute.
 * @param {Function} func - The function to throttle.
 * @returns {Function} A new function that enforces the throttling behavior.
 */
function throttle(func) {
  let lastRunTime = -Infinity; // Initialize with a time before any possible invocation

  return function() {
    const now = Date.now(); // Get current time in milliseconds

    // If the current time is at least 60 seconds (60000 ms) after the last run, execute the function
    if (now - lastRunTime >= 60000) {
      func();                  // Call the original function
      lastRunTime = now;       // Update the last run time
    }
  };
}

const runOncePerMinute = throttle(() => {
  console.log("This function runs once per minute.");
});

