import ipaddress

def list_host_addresses(subnet):
    """Return a list of all host IP addresses in the given subnet."""
    try:
        # Create a network object from the subnet (supports both IPv4 and IPv6)
        network = ipaddress.ip_network(subnet, strict=False)
        # Generate all host addresses (excluding network and broadcast)
        return list(network.hosts())
    except ValueError:
        return f"Invalid subnet: {subnet}"

