from datetime import datetime
from collections import defaultdict

def bucket_hour(timestamps):
    """
    Groups a list of timestamps by their local hour.

    Parameters:
        timestamps (List[str]): List of timestamp strings in "YYYY-MM-DD HH:MM:SS" format.

    Returns:
        dict: A dictionary mapping hour (int) to count (int).
    """
    result = defaultdict(int)
    for ts in timestamps:
        try:
            dt = datetime.strptime(ts, "%Y-%m-%d %H:%M:%S")
            hour = dt.hour
            result[hour] += 1
        except ValueError:
            print(f"Invalid timestamp: {ts}")
            return {}
    return dict(result)

import sys

def int_to_ip(n):
    """Converts a 32-bit integer to an IP address string."""
    return f"{(n >> 24) & 0xFF}.{(n >> 16) & 0xFF}.{(n >> 8) & 0xFF}.{n & 0xFF}"

def main():
    line = sys.stdin.read().strip()
    if not line:
        return

    network_part, prefix_str = line.split('/')
    prefix = int(prefix_str)

    # Parse the network part
    octets = list(map(int, network_part.split('.')))
    network_addr = (octets[0] << 24) | (octets[1] << 16) | (octets[2] << 8) | octets[3]

    host_bits = 32 - prefix

    if host_bits == 0:
        return  # No host addresses in a /32 subnet

    # Broadcast address
    broadcast = network_addr + (1 << host_bits) - 1

    start = network_addr + 1
    end = broadcast - 1

    if start > end:
        return  # No host addresses (e.g., in a /31 or /32 subnet)

    for i in range(start, end + 1):
        print(int_to_ip(i))

if __name__ == "__main__":
    main()

import sys

def ip_to_int(ip_str):
    parts = list(map(int, ip_str.split('.')))
    return (parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3]

def int_to_ip(int_val):
    return '.'.join(str((int_val >> (24 - i * 8)) & 0xFF) for i in range(4))

def main():
    ip_str = sys.stdin.read().strip()
    if '/' not in ip_str:
        print("Invalid input format. Use CIDR notation.")
        return

    network_part, prefix_part = ip_str.split('/')
    prefix = int(prefix_part)

    ip_int = ip_to_int(network_part)
    mask = ((1 << prefix) - 1) << (32 - prefix)
    network = ip_int & mask
    broadcast = network | ((1 << (32 - prefix)) - 1)

    start = network + 1
    end = broadcast - 1

    for i in range(start, end + 1):
        print(int_to_ip(i))

