def find_prime_factors(n):
    factors = []
    if n < 2:
        return []
    # Handle factor 2 separately
    while n % 2 == 0:
        factors.append(2)
        n = n // 2
    # Check odd numbers up to sqrt(n)
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n = n // i
        i += 2
    # If remaining n is a prime > 2
    if n > 1:
        factors.append(n)
    return factors

