import datetime
from zoneinfo import ZoneInfo

def get_local_timezone():
    """Get the system's local timezone."""
    return ZoneInfo(datetime.datetime.now().astimezone().tzinfo.zone)

def bucket_by_hour(timestamps):
    """Bucket timestamps by their local hour of day."""
    local_tz = get_local_timezone()
    buckets = {}

    for ts_str in timestamps:
        # Parse the timestamp (assuming it's in local time or UTC)
        ts = datetime.datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S")

        # Convert to local time zone
        ts_local = ts.replace(tzinfo=local_tz)

        hour = ts_local.hour
        if hour not in buckets:
            buckets[hour] = []
        buckets[hour].append(ts_local)

    return buckets

