def topological_sort(dependencies):
    """
    Perform topological sorting on a set of tasks and their dependencies.

    Args:
        dependencies (dict): A dictionary mapping each task to a list of its dependencies.
                            E.g., {'task1': ['task2', 'task3']}

    Returns:
        list: A valid execution order of tasks.

    Raises:
        ValueError: If a cycle is detected in the dependencies.
    """
    # Build adjacency list and in-degree counts
    adj = {}
    in_degree = {}

    # Initialize for all tasks
    all_tasks = set(dependencies.keys())
    for task in all_tasks:
        adj[task] = []
        in_degree[task] = 0

    # Populate adjacency list and in-degree counts
    for task, deps in dependencies.items():
        for dep in deps:
            adj[dep].append(task)
            in_degree[task] += 1

    # Kahn's algorithm
    from collections import deque
    queue = deque()
    for task in in_degree:
        if in_degree[task] == 0:
            queue.append(task)

    order = []
    while queue:
        current = queue.popleft()
        order.append(current)
        for neighbor in adj[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check for cycles
    if len(order) != len(all_tasks):
        raise ValueError("Cycle detected in dependencies. No valid execution order exists.")

    return order

