import time
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

def watch_file(file_path, callback):
    """
    Monitors a specific file for changes and executes the given callback function
    whenever the file is modified, created, or deleted.

    Args:
        file_path (str): The path of the file to monitor.
        callback (function): A function to call when the file changes.
    """
    class Handler(FileSystemEventHandler):
        def __init__(self, callback):
            self.callback = callback

        def on_modified(self, event):
            if event.src_path == file_path:
                self.callback(event)

        def on_created(self, event):
            if event.src_path == file_path:
                self.callback(event)

        def on_deleted(self, event):
            if event.src_path == file_path:
                self.callback(event)

    # Initialize and start the observer
    observer = Observer()
    observer.schedule(Handler(callback), path=file_path, recursive=False)
    observer.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        # Gracefully stop the observer
        observer.stop()
        observer.join()

