from collections import deque

def topo_sort(pairs):
    # Step 1: Collect all unique tasks
    tasks = set()
    for task, dep in pairs:
        tasks.add(task)
        tasks.add(dep)

    # If no tasks exist, return an empty list
    if not tasks:
        return []

    # Step 2: Build adjacency list and in-degree dictionary
    adj = {task: [] for task in tasks}
    in_degree = {task: 0 for task in tasks}

    for task, dep in pairs:
        adj[dep].append(task)
        in_degree[task] += 1

    # Step 3: Apply Kahn's algorithm
    queue = deque()
    for task in in_degree:
        if in_degree[task] == 0:
            queue.append(task)

    topo_order = []
    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Step 4: Check for cycles
    if len(topo_order) != len(tasks):
        raise ValueError("Cycle detected in dependencies.")

    return topo_order

