import re
import datetime
import sys
import json

def parse_log_line(line):
    """Parses a line of log into structured fields if valid."""
    # Regex pattern to match the log line format
    log_pattern = re.compile(
        r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) \[([^\]]+)\] (.*$)',
        re.DOTALL
    )
    match = log_pattern.match(line.strip())

    if not match:
        return None  # Line does not match expected format

    timestamp_str = match.group(1)
    level = match.group(2)
    message = match.group(3)

    # Parse timestamp
    try:
        datetime.datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return None  # Invalid timestamp format

    return {
        "timestamp": timestamp_str,
        "level": level,
        "message": message
    }

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        result = parse_log_line(line)
        if result:
            print(json.dumps(result))

