import math

def distance(p1, p2):
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def cluster_points(points, radius, min_size):
    clusters = []
    assigned = [False] * len(points)

    for i in range(len(points)):
        if not assigned[i]:
            # Start a new cluster with this point
            cluster = [points[i]]
            assigned[i] = True

            # Expand the cluster by adding any unassigned point within the radius
            for j in range(len(points)):
                if not assigned[j]:
                    in_cluster = False
                    for p in cluster:
                        if distance(p, points[j]) <= radius:
                            in_cluster = True
                            break
                    if in_cluster:
                        cluster.append(points[j])
                        assigned[j] = True

            # Only add the cluster if it meets the size requirement
            if len(cluster) >= min_size:
                clusters.append(cluster)

    return clusters

def prime_factors(n):
    factors = []

    # Handle factor 2 first
    count = 0
    while n % 2 == 0:
        count += 1
        n = n // 2
    if count > 0:
        factors.append((2, count))

    # Now check odd factors from 3 up to sqrt(n)
    i = 3
    while i * i <= n:
        count = 0
        while n % i == 0:
            count += 1
            n = n // i
        if count > 0:
            factors.append((i, count))
        i += 2

    # If remaining n is a prime number greater than 2
    if n > 1:
        factors.append((n, 1))

    return factors

