from statistics import mean, stdev
from typing import List, Dict, Optional

def normalize_metric_values(jobs: List[Job], group_key: str) -> List[Job]:
    grouped_jobs = {}
    for job in jobs:
        key = job.user_id  # or any grouping field
        if key not in grouped_jobs:
            grouped_jobs[key] = []
        grouped_jobs[key].append(job)

    normalized_jobs = []
    for key, group in grouped_jobs.items():
        # Compute mean and std for the group
        values = [job.metric_value for job in group if job.metric_value is not None]
        if not values:
            continue
        mean_val = mean(values)
        std_val = stdev(values)
        for job in group:
            if job.metric_value is not None:
                normalized_value = (job.metric_value - mean_val) / std_val
                job.metric_value = normalized_value
        normalized_jobs.extend(group)
    return normalized_jobs

