class Throttler:
    def __init__(self, interval):
        self.interval = interval  # Time in seconds
        self.last_call = None     # Stores the last call time

    def __call__(self, func):
        def wrapper(*args, **kwargs):
            current_time = time.time()
            # If no previous call or the time has passed the interval, allow execution
            if self.last_call is None or (current_time - self.last_call) >= self.interval:
                self.last_call = current_time
                return func(*args, **kwargs)
            else:
                return None  # Throttle — function does not execute
        return wrapper

def throttle(interval):
