def throttle(minutes):
    def decorator(func):
        last_call = None  # Tracks the last execution time of the function

        def wrapper(*args, **kwargs):
            nonlocal last_call
            now = time.time()

            if last_call is None:
                # This is the first call, allow it
                last_call = now
                return func(*args, **kwargs)
            else:
                # Check if it has been at least 'minutes' minutes since the last call
                if now - last_call >= minutes * 60:
                    last_call = now
                    return func(*args, **kwargs)
                else:
                    return None  # Function not executed due to throttling

        return wrapper

    return decorator

