class Throttle:
    def __init__(self, interval):
        self.interval = interval  # interval in seconds
        self.last_call = 0

    def __call__(self, func):
        def wrapper(*args, **kwargs):
            now = time.time()
            if now - self.last_call < self.interval:
                # Calculate the time to wait until the next allowed call
                wait_time = self.last_call + self.interval - now
                time.sleep(wait_time)
            # Update the last call time to the current time after waiting
            self.last_call = now
            return func(*args, **kwargs)
        return wrapper

