def throttle(func, interval):
    def wrapper(*args, **kwargs):
        import time
        last_call = time.time()
        def inner(*args, **kwargs):
            nonlocal last_call
            now = time.time()
            if now - last_call < interval:
                time.sleep(interval - (now - last_call))
            last_call = now
            return func(*args, **kwargs)
