def cluster_points(points, radius, min_group_size):
    import math

    n = len(points)
    if n == 0:
        return []

    # Step 1: Build adjacency list
    adj = [[] for _ in range(n)]
    radius_sq = radius * radius

    for i in range(n):
        for j in range(n):
            if i != j:
                dx = points[i][0] - points[j][0]
                dy = points[i][1] - points[j][1]
                dist_sq = dx * dx + dy * dy
                if dist_sq <= radius_sq:
                    adj[i].append(j)

    # Step 2: Find connected components using BFS
    visited = [False] * n
    labels = [-1] * n
    current_label = 0

    for i in range(n):
        if not visited[i]:
            # BFS to find connected component
            queue = [i]
            visited[i] = True
            component = [i]
            while queue:
                node = queue.pop(0)
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        component.append(neighbor)
                        queue.append(neighbor)

            # Assign label if the component is large enough
            if len(component) >= min_group_size:
                for idx in component:
                    labels[idx] = current_label
                current_label += 1

    return labels

def cluster_points(points, radius, min_size):
