    if n == 0:
        return []

    # Precompute squared radius to avoid sqrt (more efficient)
    radius_sq = radius * radius

    # Build graph of neighbors (points within radius)
    graph = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            dist_sq = dx * dx + dy * dy
            if dist_sq <= radius_sq:
                graph[i].append(j)
                graph[j].append(i)

    # Find connected components using BFS
    visited = [False] * n
    labels = [-1] * n
    current_label = 0

    for i in range(n):
        if not visited[i]:
            queue = [i]
            visited[i] = True
            component = []

            while queue:
                node = queue.pop(0)
                component.append(node)
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)

            # Check if this component is big enough
            if len(component) >= min_size:
                for node in component:
                    labels[node] = current_label
                current_label += 1

    return labels

