import re
from datetime import datetime

def parse_log_line(line: str) -> dict | None:
    # Regex to match timestamp and message parts
    pattern = r'^\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] (.+)$'
    match = re.match(pattern, line)

    if not match:
        return None  # Malformed line structure

    timestamp_str = match.group(1)
    message = match.group(2)

    # Parse timestamp
    try:
        timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return None  # Invalid timestamp format

    # Process message into key-value pairs
    parts = message.split(':', 1)
    if len(parts) != 2:
        return None  # Invalid message structure

    kv_pairs = parts[1].split(',')
    fields = {}

    for pair in kv_pairs:
        if not pair.strip():
            continue  # Skip empty entries

        try:
            key, value = pair.split('=', 1)
            fields[key.strip()] = value.strip()
        except ValueError:
            return None  # Invalid key-value pair format

    return {
        'timestamp': timestamp,
        'fields': fields
    }

