def prime_factor(n):
    if not isinstance(n, int) or n < 2:
        raise ValueError("Input must be a positive integer.")

    n = abs(n)
    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n = n // divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

