import sys

def mean(column):
    return sum(column) / len(column)

def median(column):
    sorted_col = sorted(column)
    n = len(sorted_col)
    if n % 2 == 1:
        return sorted_col[n // 2]
    else:
        return (sorted_col[n // 2 - 1] + sorted_col[n // 2]) / 2

def mode(column):
    counts = {}
    for num in column:
        counts[num] = counts.get(num, 0) + 1
    max_count = -1
    mode_val = None
    for key in counts:
        if counts[key] > max_count:
            max_count = counts[key]
            mode_val = key
    return mode_val

def variance(column):
    mean_val = mean(column)
    squared_diffs = [(x - mean_val) ** 2 for x in column]
    return sum(squared_diffs) / len(column)

