async def rate_limit_middleware(request: Request, call_next):
    endpoint = request.url.path

    if endpoint == "/jobs/{job_id}":
        now = datetime.now()
        key = endpoint

        if key not in rate_limits:
            rate_limits[key] = {
                "count": 0,
                "timestamp": now
            }
        else:
            # Check if more than one minute has passed
            if (now - rate_limits[key]["timestamp"]).total_seconds() > 60:
                rate_limits[key]["count"] = 0
