            else:
                rate_limits[key]["count"] += 1
                if rate_limits[key]["count"] > 1:
                    raise HTTPException(
                        status_code=429,
                        detail="Too many requests. Please try again later."
                    )

        return await call_next(request)

    else:
        return await call_next(request)

