def prime_factors(n):
    if n < 2:
        return []
    n = abs(n)  # Work with absolute value for negative inputs
    factors = []

    # Handle the factor 2
    while n % 2 == 0:
        factors.append(2)
        n //= 2

    # Check for odd divisors from 3 up to sqrt(n)
    divisor = 3
    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 2

    # If n is still greater than 1, it's a prime
    if n > 1:
        factors.append(n)

    return factors

def prime_factors(n):
    if n <= 1:
        return []

    factors = []
    n = abs(n)  # Work with absolute value

    # Handle even factors first
    while n % 2 == 0:
        factors.append(2)
        n = n // 2

    # Check odd numbers starting from 3
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n = n // i
        i += 2  # Continue with odd numbers only

    # If remaining number is a prime > 2
    if n > 1:
        factors.append(n)

    return factors

