import sys
import time

def throttle(func):
    last_time = None  # Store the last time the function was called

    def wrapper(*args, **kwargs):
        nonlocal last_time
        current_time = time.time()  # Current time in seconds

        # First call: no throttling needed
        if last_time is None:
            last_time = current_time
            return func(*args, **kwargs)

        # Otherwise, check the time difference
        delta = current_time - last_time
        if delta < 60:
            # Compute the next minute
            next_minute = (current_time // 60 + 1) * 60
            sleep_time = next_minute - current_time
            time.sleep(sleep_time)

        # Update the last call time
        last_time = current_time
        return func(*args, **kwargs)

    return wrapper

