def throttle(func):
    """Decorator to throttle a function to run at most once per minute."""
    def wrapper(*args, **kwargs):
        now = time.time()
        if not hasattr(wrapper, 'last_call') or now - wrapper.last_call > 60:
            wrapper.last_call = now
            return func(*args, **kwargs)
        else:
            return None
    return wrapper

