import math

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root != y_root:
            self.parent[y_root] = x_root

def cluster_points(points, radius, min_samples):
    """
    Clusters a set of 2D points by density using the Delaunay-based method.

    Parameters:
    - points: List of 2D points (tuples of (x, y)).
    - radius: Distance threshold for considering two points as neighbors.
    - min_samples: Minimum number of points needed in a cluster.

    Returns:
    - List of clusters, each represented as a list of points (tuples).
    """
    if not points:
        return []

    n = len(points)
    dsu = DSU(n)

    # Build graph: connect points if their Euclidean distance is <= radius
    for i in range(n):
        for j in range(i + 1, n):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            distance = math.sqrt(dx ** 2 + dy ** 2)
            if distance <= radius:
                dsu.union(i, j)

    # Group points by root in the DSU
    groups = {}
    for i in range(n):
        root = dsu.find(i)
        if root not in groups:
            groups[root] = []
        groups[root].append(i)

    # Filter groups that have at least min_samples
    clusters = []
    for group in groups.values():
        if len(group) >= min_samples:
            clusters.append([points[i] for i in group])

    return clusters

