def order_tasks(dependencies: list[tuple[str, str]]) -> list[str]:
    """Determine a valid execution order for tasks based on dependencies.

    Args:
        dependencies: List of (task1, task2) pairs indicating task1 must come before task2.

    Returns:
        A list of task names in a valid execution order.

    Raises:
        ValueError: If there's a cycle in the dependencies.
    """
    # Build the graph and in-degree counts
    graph = {}
    in_degree = {}

    tasks = set()
    for a, b in dependencies:
        tasks.add(a)
        tasks.add(b)
        if a not in graph:
            graph[a] = []
        graph[a].append(b)
        if b not in in_degree:
            in_degree[b] = 0
        in_degree[b] += 1

    if not tasks:
        return []

    # Initialize the queue with nodes of in-degree 0
    queue = deque()
    for task in tasks:
        if task not in in_degree or in_degree[task] == 0:
            queue.append(task)

    order = []
    while queue:
        task = queue.popleft()
        order.append(task)
        if task in graph:
            for neighbor in graph[task]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

    if len(order) != len(tasks):
        raise ValueError("Cycle detected in dependencies.")

    return order

