    for task, dep in dependencies:
        nodes.add(task)
        nodes.add(dep)
        if dep not in adj:
            adj[dep] = []
        adj[dep].append(task)
        in_degree[task] = in_degree.get(task, 0) + 1

    queue = deque()
    for node in nodes:
        if in_degree.get(node, 0) == 0:
            queue.append(node)

    order = []
    while queue:
        current = queue.popleft()
        order.append(current)
        for neighbor in adj.get(current, []):
            in_degree[neighbor] -= 1
