def topological_sort(
    dependencies: list[tuple[str, str]],
) -> list[str]:
    """Return a valid execution order for tasks with dependencies, or raise an error if there's a cycle."""
    # Collect all tasks
    tasks = set()
    for a, b in dependencies:
        tasks.add(a)
        tasks.add(b)
    if not tasks:
        return []

    # Build graph and in-degrees
    graph = {}
    in_degree = {}
    for task in tasks:
        graph[task] = []
        in_degree[task] = 0

    for a, b in dependencies:
        graph[a].append(b)
        in_degree[b] += 1

    # Kahn's algorithm
    queue = [task for task in tasks if in_degree[task] == 0]
    order = []

    while queue:
        current = queue.pop(0)
        order.append(current)
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) != len(tasks):
        raise ValueError("Cycle detected in dependencies.")

    return order

import sys
import math

def main():
    data = sys.stdin.read().splitlines()
    columns = []

    # Step 1: Read data into columns
    for line in data:
        parts = line.strip().split()
        if not parts:
            continue
        for i in range(len(parts)):
            if i >= len(columns):
                columns.append([])
            columns[i].append(float(parts[i]))

    # Step 2: Standardize each column
    for i in range(len(columns)):
        col = columns[i]
        mean = sum(col) / len(col)
        squared_diffs = sum((x - mean) ** 2 for x in col)
        std_dev = math.sqrt(squared_diffs / len(col))

        if std_dev == 0:
            for j in range(len(col)):
                columns[i][j] = 0.0
        else:
            for j in range(len(col)):
                columns[i][j] = (columns[i][j] - mean) / std_dev

    # Step 3: Reconstruct output
    output = []
    for row_idx, line in enumerate(data):
        stripped_line = line.strip()
        if not stripped_line:
            output.append('')
            continue
        transformed_parts = []
        for col_idx in range(len(columns)):
            transformed_parts.append(str(columns[col_idx][row_idx]))
        output_line = ' '.join(transformed_parts)
        output.append(output_line)

    print('\n'.join(output))

if __name__ == '__main__':
    main()
